@spec tuning_spec  src=tests/specs/tuning_spec.lua  loc=925  cases=58
@exercises tuning (tuning)
@surface   tuning.derive, tuning.stepToParts, tuning.genRank2, tuning.stepToMidi, tuning.midiToStep, tuning.scalaPitch, tuning.unrooted, tuning.removeStep, tuning.sortSteps, tuning.midiName, tuning.stepWindow, tuning.parseScalaFile, tuning.parseScalaPitches, tuning.scalaToTemper, tuning.genEqual, tuning.edoDegrees, tuning.degreesToSpec, tuning.genHarmonics, tuning.genSubharmonics, tuning.parseChord, tuning.genChord, tuning.genCPS, tuning.genDiamond, tuning.nextMosSize, tuning.mosInfo, tuning.coords, tuning.isTarget, tuning.stepClass, tuning.shortlist

# Intent
  Pins tuning.lua's pure display + derivation layer: the Option-B nameless
  step labels, the derived octaveStep / cellWidth fields, and the coordinate
  conversions between MIDI and step-octave. Realisation invariants (I1-I5)
  live in tm_tuning_spec; projection wiring in view_context_spec.

# Helpers
  @fn nameless(cents)  @ 10-12
  @fn stepText(temper, step, octave)  @ 16-19
      -- The two label parts joined, so a case that is about the whole label can
      -- assert it as one string.
  @fn rooted(root)  @ 22-28
      -- A 12EDO scale with the root fields the case is about; everything else default.
  @fn authored(root)  @ 32-37
      -- The same 12EDO in the shape a step edit sees: pitch tokens, names densified
      -- to '' as cloneForEdit leaves them, so sortSteps and removeStep can drive it.
  @fn meantone12()  @ 41-45
      -- Quarter-comma meantone's twelve-note MOS (Eb..G#, C at the unison): an
      -- unequal scale, so a step's two neighbours sit at different distances.
  @fn nearly(got, want, why)  @ 49-51
      -- A candidate's cents and strain are irrational in general, so a case that names
      -- one names it to four places.
  @fn half12()  @ 55-59
      -- 12EDO written as six equal steps of a half-octave period: a step index that
      -- recurs inside the octave, on a step a tritone from the one it repeats.
  @fn bp13()  @ 63-68
      -- Bohlen-Pierce's thirteen equal divisions of 3/1, rooted so step 1 is C4: a
      -- period that is not the octave, so the step an octave up is a different step.
  @fn soundsA415(temper, step, why)  @ 76-80
      -- What the rooted step sounds, as (midi, detune); the deletions and sorts below
      -- all claim to leave it alone.

# Cases
  @case 'preset EDOs derive width 3 and a past-the-end octaveStep'  [pure]  @ 84-94
  @case 'named step renders name + octave'  [pure]  @ 98-103
  @case 'a negative octave renders as its magnitude and reports the sign'  [pure]  @ 107-116
  @case 'the octaveStep bump owns the sign: a step that crosses zero is not negative'  [pure]  @ 120-127
  @case 'nameless step falls back to degree-octave with a dash'  [pure]  @ 131-139
  @case 'nameless scale past 9 steps widens the cell for 2-digit degrees'  [pure]  @ 143-150
  @case 'sub-octave period widens the octave field for 2-digit octaves'  [pure]  @ 154-163
  @case 'a root numbering the octaves near zero narrows the field'  [pure]  @ 167-187
  @case 'a root numbering the range low makes the bottom end the wider'  [pure]  @ 191-203
  @case 'derive recomputes width when names are dropped'  [pure]  @ 207-215
  @case 'partially named scale: named steps keep their label, blanks fall back'  [pure]  @ 219-226
  @case 'scalaPitch parses ratios, cents, bare integers and n\\m steps'  [pure]  @ 230-244
  @case 'derive compiles pitches → cents and periodPitch → period'  [pure]  @ 248-256
  @case 'derive reduces an authored root to rootCents + octaveBase'  [pure]  @ 260-270
  @case 'a preset states no root and derives the default (0,0) = (1,-1)'  [pure]  @ 274-283
  @case 'unrooted is the library form: the four dropped, the stamps back at the default'  [pure]  @ 287-298
  @case 'a deleted step takes the root\'s index down with it'  [pure]  @ 302-312
  @case 'deleting the rooted step restates the root on the unison'  [pure]  @ 316-333
  @case 'a step sorted below the root carries the root\'s index'  [pure]  @ 337-346
  @case 'retuning the rooted step moves the scale, not the root'  [pure]  @ 350-363
  @case 'a temper stating no root comes through both edits unstamped'  [pure]  @ 367-378
  @case 'midiName spells a pitch in the untempered twelve names'  [pure]  @ 382-388
  @case 'the default root reduces the conversions to MIDI-relative arithmetic'  [pure]  @ 392-407
  @case 'stepWindow halves the distance to each neighbour, wrapping at both ends'  [pure]  @ 411-424
  @case 'stepWindow under an unequal scale reports two different halves'  [pure]  @ 428-440
  @case 'a flattened root moves every pitch by its offset and renames nothing'  [pure]  @ 444-466
  @case 'an octave-shifted root renames every octave and moves no pitch'  [pure]  @ 470-486
  @case 'the conversions invert each other at every root'  [pure]  @ 490-503
  @case 'EDO presets carry n\\m source tokens that derive back to their cents'  [pure]  @ 507-514
  @case 'parseScalaFile strips comments, description and count; returns pitch tokens'  [pure]  @ 518-526
  @case 'parseScalaPitches keeps every non-comment, non-blank line'  [pure]  @ 530-535
  @case 'scalaToTemper prepends the unison, splits the period, flags periodAsStep'  [pure]  @ 539-550
  @case 'scalaToTemper sorts unordered pitches ascending; widest becomes the period'  [pure]  @ 554-563
  @case 'scalaToTemper rejects an unparseable token'  [pure]  @ 567-572
  @case 'genEqual: full EDO and a diatonic subset, base implicit, period last'  [pure]  @ 576-588
  @case 'edoDegrees: relative cumulates, absolute sorts; non-octave equave suffixes'  [pure]  @ 592-600
  @case 'degreesToSpec round-trips edoDegrees in both modes'  [pure]  @ 604-608
  @case 'genHarmonics / genSubharmonics: rooted on the low harmonic, top is period'  [pure]  @ 612-621
  @case 'genChord: otonal vs inverted, last member is the period'  [pure]  @ 625-637
  @case 'parseChord rejects fewer than two notes or non-integers'  [pure]  @ 641-645
  @case 'genCPS: hexany rooted on the smallest product, 1/1 first, ascending'  [pure]  @ 649-655
  @case 'genDiamond: the 9-diamond entire, and the counts either side of it'  [pure]  @ 659-669
  @case 'genDiamond: the prime limit filters in place, and leaves a tritone hole'  [pure]  @ 673-684
  @case 'genRank2: pure-fifth size 7 / up 5 is Pythagorean major, 1/1 first'  [pure]  @ 688-694
  @case 'genRank2: size 4 / up 2 matches the Scale Workshop worked example'  [pure]  @ 698-703
  @case 'genRank2: irrational (EDO-step) generator emits cents tokens'  [pure]  @ 707-712
  @case 'nextMosSize / mosInfo: pure-fifth ladder 2->3->5->7->12; 7 is 5L 2s'  [pure]  @ 716-728
  @case 'coords: the exponents of the odd primes, prime 2 divided out'  [pure]  @ 732-742
  @case 'coords: an unreduced token reads as the interval it states'  [pure]  @ 746-751
  @case 'coords: a token that is not a ratio carries none'  [pure]  @ 755-761
  @case 'isTarget: a temper whose every pitch factorises, and nothing else'  [pure]  @ 765-773
  @case 'stepClass: an exact octave shares a class, and nothing else does'  [pure]  @ 777-803
  @case 'shortlist: the key step holds the unison, and the tonic does not move'  [pure]  @ 807-825
  @case 'shortlist: the rival spellings of a step, nearest first'  [pure]  @ 829-845
  @case 'shortlist: the hole at the tritone is the target\'s, not the step\'s'  [pure]  @ 849-860
  @case 'shortlist: widened, the hole reaches the nearest points either side'  [pure]  @ 864-879
  @case 'shortlist: an unequal notation strains by the side the point lies on'  [pure]  @ 883-895
  @case 'shortlist: one window serves the strand, in every register'  [pure]  @ 899-923

